import { pick } from 'es-toolkit/object/pick';
import { sumBy } from 'es-toolkit/math/sumBy';
import toNumber from 'es-toolkit/compat/toNumber';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

